using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEngine.SceneManagement;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;using UnityEditor;using Newtonsoft.Json;
public static class B2Play {
 static string O=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../../Docs/Review/2026-11-09_B2_Cooling/"));static GameObject player;static MonoBehaviour look;static Transform pivot;static Vector3 savedPosition,from;static Quaternion savedYaw,savedPitch;static bool savedLook,running;static int stage,first,last;static double start;static InputSettings.BackgroundBehavior bg;static InputSettings.EditorInputBehaviorInPlayMode eb;static List<object> results=new List<object>();static List<string> errors=new List<string>();static List<float> frameTimes=new List<float>();
 public static object Prepare(){if(Application.isPlaying||SceneManager.GetActiveScene().isDirty)throw new Exception("Saved edit required");SessionState.SetBool("B2Play.Background",Application.runInBackground);Application.runInBackground=true;return new{mouse=Mouse.current.enabled,keyboard=Keyboard.current.enabled};}
 public static object Begin(){if(!Application.isPlaying||!SceneManager.GetActiveScene().path.EndsWith("Level_B2_Circular.unity"))throw new Exception("B2 Play required");if(!Mouse.current.enabled||!Keyboard.current.enabled)throw new Exception("Native device disabled");player=SceneManager.GetActiveScene().GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));look=player.GetComponentsInChildren<MonoBehaviour>(true).Single(c=>c.GetType().Name=="PlayerLook");pivot=(Transform)look.GetType().GetField("cameraRoot",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(look);savedPosition=player.transform.position;savedYaw=player.transform.rotation;savedPitch=pivot.localRotation;savedLook=look.enabled;look.enabled=false;pivot.localRotation=Quaternion.identity;bg=InputSystem.settings.backgroundBehavior;eb=InputSystem.settings.editorInputBehaviorInPlayMode;InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;InputSystem.settings.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;EditorWindow.GetWindow(typeof(Editor).Assembly.GetType("UnityEditor.GameView")).Focus();results.Clear();errors.Clear();running=true;stage=0;Next();EditorApplication.update+=Tick;Application.logMessageReceived+=Log;AssemblyReloadEvents.beforeAssemblyReload+=Cancel;EditorApplication.playModeStateChanged+=Mode;return new{started=true,stages=4};}
 static void Next(){var cc=player.GetComponent<CharacterController>();var p=stage==0?new Vector3(0,0,-6.5f):stage==1?new Vector3(-6.2f,.36f,-7.05f):stage==2?new Vector3(6.2f,.36f,-7.05f):new Vector3(-4.5f,3.6f,4.5f);cc.enabled=false;player.transform.SetPositionAndRotation(new Vector3(19,-34,-1)+p+Vector3.up*(cc.height*.5f-cc.center.y+.05f),Quaternion.Euler(0,stage==3?90:0,0));cc.enabled=true;Physics.SyncTransforms();from=player.transform.position;first=last=Time.frameCount;start=EditorApplication.timeSinceStartup;frameTimes.Clear();}
 static void Log(string m,string st,LogType t){if(t==LogType.Error||t==LogType.Exception)errors.Add(m);}
 static void Mode(PlayModeStateChange m){if(m==PlayModeStateChange.ExitingPlayMode)Cancel();}static void Cancel(){if(running)End(false);}
 static void Tick(){try{if(!Application.isPlaying){End(false);return;}EditorApplication.QueuePlayerLoopUpdate();double elapsed=EditorApplication.timeSinceStartup-start;InputSystem.QueueStateEvent(Keyboard.current,elapsed<.9?new KeyboardState(Key.W):new KeyboardState());if(Time.frameCount!=last){last=Time.frameCount;if(elapsed>1)frameTimes.Add(Time.unscaledDeltaTime*1000);}if(elapsed<3.2)return;var delta=player.transform.position-from;var cc=player.GetComponent<CharacterController>();var ms=frameTimes.OrderBy(x=>x).ToArray();results.Add(new{stage,name=new[]{"ground","west_stairs","east_stairs","upper_walkway"}[stage],frames=Time.frameCount-first,distance=new Vector2(delta.x,delta.z).magnitude,rise=delta.y,grounded=cc.isGrounded,medianMs=ms.Length>0?ms[ms.Length/2]:0,mouse=Mouse.current.enabled,keyboard=Keyboard.current.enabled,camera=Camera.main?Camera.main.transform.position.ToString():null});stage++;if(stage<4)Next();else End(true);}catch(Exception e){errors.Add(e.ToString());End(false);}}
 static void End(bool complete){running=false;EditorApplication.update-=Tick;Application.logMessageReceived-=Log;AssemblyReloadEvents.beforeAssemblyReload-=Cancel;EditorApplication.playModeStateChanged-=Mode;try{InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState());File.WriteAllText(O+"play.json",JsonConvert.SerializeObject(new{complete,results,errors,mouse=Mouse.current.enabled,keyboard=Keyboard.current.enabled},Formatting.Indented));}finally{InputSystem.settings.backgroundBehavior=bg;InputSystem.settings.editorInputBehaviorInPlayMode=eb;if(player){var cc=player.GetComponent<CharacterController>();bool on=cc.enabled;cc.enabled=false;player.transform.SetPositionAndRotation(savedPosition,savedYaw);cc.enabled=on;}if(pivot)pivot.localRotation=savedPitch;if(look)look.enabled=savedLook;}}
 public static object Restore(){if(Application.isPlaying)throw new Exception("Exit Play first");Application.runInBackground=SessionState.GetBool("B2Play.Background",false);return new{mouse=Mouse.current.enabled,keyboard=Keyboard.current.enabled,Application.runInBackground,dirty=SceneManager.GetActiveScene().isDirty};}
}
